`timescale 1ns/1ps
module banked_unified_memory_ecc #(parameter int BANKS=16,BANK_ADDR_WIDTH=10,DATA_WIDTH=64,BYTE_EN_WIDTH=DATA_WIDTH/8,TXN_ID_WIDTH=12)(input logic clk,rst_n,input logic [BANKS-1:0] cmd_valid,cmd_write,input logic [BANKS-1:0][BANK_ADDR_WIDTH-1:0] cmd_addr,input logic [BANKS-1:0][DATA_WIDTH-1:0] cmd_wdata,input logic [BANKS-1:0][BYTE_EN_WIDTH-1:0] cmd_be,input logic [BANKS-1:0][TXN_ID_WIDTH-1:0] cmd_txn_id,output logic [BANKS-1:0] rsp_valid,output logic [BANKS-1:0][DATA_WIDTH-1:0] rsp_rdata,output logic [BANKS-1:0][TXN_ID_WIDTH-1:0] rsp_txn_id,output logic [BANKS-1:0] rsp_ecc_corrected,rsp_ecc_uncorrectable);
localparam int CODE_W=72; localparam int DEPTH=(1<<BANK_ADDR_WIDTH); logic [CODE_W-1:0] mem[BANKS][DEPTH]; integer b,i; genvar g; generate for(g=0;g<BANKS;g=g+1) begin:GEN_ECC logic [71:0] local_enc; logic [63:0] local_dec; logic local_single,local_double,local_corrected; logic [63:0] local_write_data; integer bi; always_comb begin local_write_data=local_dec; for(bi=0;bi<BYTE_EN_WIDTH;bi=bi+1) if(cmd_be[g][bi]) local_write_data[bi*8 +:8]=cmd_wdata[g][bi*8 +:8]; end ecc_secded_64 local_ecc(.data_in(local_write_data),.codeword_out(local_enc),.codeword_in(mem[g][cmd_addr[g]]),.data_out(local_dec),.single_error(local_single),.double_error(local_double),.corrected_error(local_corrected)); end endgenerate
always_ff @(posedge clk or negedge rst_n) begin if(!rst_n) begin rsp_valid<='0; rsp_rdata<='0; rsp_txn_id<='0; rsp_ecc_corrected<='0; rsp_ecc_uncorrectable<='0; end else begin rsp_valid<='0; rsp_ecc_corrected<='0; rsp_ecc_uncorrectable<='0; for(b=0;b<BANKS;b=b+1) if(cmd_valid[b]) begin rsp_valid[b]<=1; rsp_txn_id[b]<=cmd_txn_id[b]; if(cmd_write[b]) mem[b][cmd_addr[b]]<=GEN_ECC[b].local_enc; else begin rsp_rdata[b]<=GEN_ECC[b].local_dec; rsp_ecc_corrected[b]<=GEN_ECC[b].local_corrected; rsp_ecc_uncorrectable[b]<=GEN_ECC[b].local_double; end end end end endmodule
